/* @jsx h */
// linear: your Linear board in a pane beside the transcript.
//
// /linear                  open the pane (projects → milestone → issues → detail)
// /linear CND-123          open one issue's detail
// /linear mine             my open issues, across teams
// /linear refresh          fetch again now
// /linear prompts          the plan / execute / product templates, editable
// /linear draft on|off     buttons fill the composer instead of sending
// /linear help             every form
// /linear close            close the pane
//
// This file binds `$` into a Host, registers the hooks and draws the pane.
// The state and everything that changes it live in `model.ts`, which the
// tests drive through a fake Host. Data comes from Linear's GraphQL API
// through `$.http.fetch`, with the key from the plugin's `apiKey` config or
// `LINEAR_API_KEY`. Pressing plan, execute or product renders a template over
// the issue and submits it into this session from a timer (a submit inside a
// hook is refused by the host).
//
// Never name a local `h` in this file: every JSX tag compiles to a call of `h`.

import type { Elements, EngineInterface, Register, RenderElement } from 'claude-code'
import { ARGUMENT_HINT } from './args.ts'
import { firstLines, windowOf } from './layout.ts'
import type { Layout } from './layout.ts'
import { ACTION_KINDS, currentMilestone } from './lib.ts'
import type { ActionKind, IssueDetail, IssueSummary, Project } from './lib.ts'
import {
  PANE_ID,
  PLUGIN,
  back,
  bindSource,
  briefCharsOf,
  closePane,
  filteredIssues,
  focusPastEdge,
  hasPicker,
  isLoading,
  isPaused,
  listRoom,
  markClosed,
  moveWindow,
  openPaneQuietly,
  pickMilestone,
  pressAction,
  pressEditPrompt,
  pressRefresh,
  refreshCurrent,
  rehydrate,
  resetPrompt,
  resetState,
  reseat,
  runCommand,
  safeMessage,
  seatDrawn,
  selectProject,
  selectRow,
  showDetail,
  showPrompts,
  shownIssue,
  state,
  templatePreview,
  toggleDraft,
  turnCompleted,
  turnStarted,
} from './model.ts'
import type { Host } from './model.ts'
import { DEFAULT_TEMPLATES, PLACEHOLDERS, firstLine } from './prompts.ts'
import { issueRow, projectRow } from './rows.ts'
import { cleanText, field, fit, monthDay, percent, plural, relativeTime, safeHref, sanitizeMarkdown, truncateTo } from './text.ts'

type Ui = Pick<Elements['terminal'], 'Box' | 'Text' | 'Button' | 'Select' | 'Link' | 'Code'>

/** Comments drawn in a budgeted detail, and rows each takes. */
const INLINE_COMMENTS = 2
const INLINE_COMMENT_ROWS = 2
const DETAIL_HEAD_ROWS = 4
const MIN_DESCRIPTION_ROWS = 3
/** Rows a project summary spends before its milestones: name, facts, link, hint. */
const SUMMARY_FIXED_ROWS = 4

// ---- drawing ---------------------------------------------------------------

/** What every drawing function needs: the elements, the engine, the seat, and the issues filtered once. */
type Frame = { ui: Ui; engine: Host; layout: Exclude<Layout, { mode: 'narrow' }>; issues: IssueSummary[] }

/** One row of text, cut to `width`. */
function textLine(f: Frame, width: number, text: string, dim = true): RenderElement {
  const { Text } = f.ui
  return <Text dimColor={dim} wrap="truncate-end">{truncateTo(text, width)}</Text>
}

function crumbs(): string[] {
  const out = [state.teamName]
  const project = state.projects.find(p => p.id === state.selectedProjectId)
  const inList = state.view === 'issues' || state.view === 'detail'
  if (inList && state.scope?.kind === 'mine') out.push('mine')
  else if (inList && project) out.push(project.name)
  if (state.view === 'issues' && state.milestoneFilter !== 'all') {
    const milestone = project?.milestones.find(m => m.id === state.milestoneFilter)
    if (milestone) out.push(milestone.name)
  }
  if (state.view === 'detail' && state.selectedIssue) out.push(state.selectedIssue)
  if (state.view === 'prompts') out.push('prompts')
  return out
}

function titleRow(f: Frame): RenderElement {
  const { Text } = f.ui
  // the engine's close mark sits over the top-right cells of the first row
  const title = truncateTo(`◆ ${PLUGIN} · ${crumbs().join(' › ')}`, Math.max(10, f.layout.columns - 3))
  return <Text bold wrap="truncate-end">{title}</Text>
}

function buttonsRow(f: Frame): RenderElement {
  const { Box, Button } = f.ui
  const { engine } = f
  return (
    <Box flexDirection="row" columnGap={1}>
      {state.view !== 'projects' && <Button key="linear:back" label="back" dimColor onPress={() => void back(engine)} />}
      <Button key="linear:refresh" label={isLoading() ? 'refreshing…' : 'refresh'} dimColor onPress={() => void pressRefresh(engine)} />
      <Button key="linear:draft" label={`draft: ${state.draftMode ? 'on' : 'off'}`} dimColor onPress={() => toggleDraft(engine)} />
      <Button key="linear:prompts" label="prompts" dimColor onPress={() => showPrompts(engine)} />
      <Button key="linear:close" label="close" dimColor onPress={() => void closePane(engine)} />
    </Box>
  )
}

function footerParts(f: Frame): string[] {
  const parts: string[] = []
  if (state.view === 'projects') parts.push(plural(state.projects.length, 'project'))
  if (state.view === 'issues') parts.push(`${f.issues.length} open`)
  if (state.view === 'detail' && state.detail) parts.push(`updated ${relativeTime(state.detail.updatedAt, state.clock)}`)
  const at = state.view === 'projects' ? state.fetchedAt.projects : state.view === 'issues' ? state.fetchedAt.issues : state.fetchedAt.detail
  if (isLoading()) parts.push('refreshing…')
  else if (at) parts.push(`refreshed ${relativeTime(new Date(at).toISOString(), state.clock)}`)
  if (isPaused()) parts.push('rate limited · polling paused')
  parts.push(state.view === 'prompts' ? 'edit fills the composer' : state.view === 'detail' ? 'Esc back' : 'Esc back · ↑↓ select · Enter open')
  return parts
}

function footerRow(f: Frame): RenderElement {
  const { Text } = f.ui
  const width = f.layout.columns
  if (state.errorText) return <Text color="red" wrap="truncate-end">{truncateTo(state.errorText, width)}</Text>
  return textLine(f, width, footerParts(f).join(' · '))
}

type Row = { key: string; text: string; selected: boolean; onPress: () => void }

/** The windowed list as plain buttons with edge rows the focus ring can walk onto. */
function listRows(f: Frame, rows: Row[], offset: number, room: number, width: number): RenderElement[] {
  const { Button, Text } = f.ui
  const listStatus = state.view === 'projects' ? state.status.projects : state.status.issues
  if (rows.length === 0) return [<Text dimColor>{listStatus === 'loading' ? 'loading…' : 'nothing open here'}</Text>]
  const listWindow = windowOf(rows.length, offset, room)
  const page = Math.max(1, room - 2)
  const out: RenderElement[] = []
  if (listWindow.above > 0) {
    out.push(<Button key="edge:up" plain dimColor label={fit(`  ↑ ${listWindow.above} more`, width)} onPress={() => moveWindow(f.engine, -page)} />)
  }
  for (const row of rows.slice(listWindow.start, listWindow.end)) {
    out.push(<Button key={row.key} plain dimColor={!row.selected} autoFocus={row.selected ? true : undefined} label={row.text} onPress={row.onPress} />)
  }
  if (listWindow.below > 0) {
    out.push(<Button key="edge:down" plain dimColor label={fit(`  ↓ ${listWindow.below} more`, width)} onPress={() => moveWindow(f.engine, page)} />)
  }
  return out
}

const projectRows = (f: Frame, width: number): Row[] =>
  state.projects.map(p => ({
    key: `row:${p.id}`,
    text: projectRow(p, width, p.id === state.selectedProjectId),
    selected: p.id === state.selectedProjectId,
    onPress: () => selectProject(f.engine, p.id),
  }))

const issueRows = (f: Frame, width: number): Row[] =>
  f.issues.map(i => ({
    key: `row:${i.identifier}`,
    text: issueRow(i, width, i.identifier === state.selectedIssue),
    selected: i.identifier === state.selectedIssue,
    onPress: () => void showDetail(f.engine, i.identifier),
  }))

function milestoneSelect(f: Frame): RenderElement | undefined {
  const { Select } = f.ui
  const project = state.projects.find(p => p.id === state.selectedProjectId)
  if (!hasPicker() || !project) return undefined
  const options = [{ value: 'all', label: 'all milestones' }, ...project.milestones.map(m => ({ value: m.id, label: m.name }))]
  return <Select key="linear:milestone" label="milestone" options={options} value={state.milestoneFilter} onSelect={value => pickMilestone(f.engine, value)} />
}

function listColumn(f: Frame, width: number): RenderElement {
  const { Box } = f.ui
  const room = listRoom()
  if (state.view === 'projects') {
    return <Box flexDirection="column" width={width}>{listRows(f, projectRows(f, width), state.projectOffset, room, width)}</Box>
  }
  return (
    <Box flexDirection="column" width={width}>
      {milestoneSelect(f)}
      {listRows(f, issueRows(f, width), state.issueOffset, room, width)}
    </Box>
  )
}

function milestoneLine(m: Project['milestones'][number], isCurrent: boolean): string {
  const due = m.targetDate ? ` · ${monthDay(m.targetDate)}` : ''
  return `${isCurrent ? '▸' : ' '} ${m.name} · ${percent(m.progress)}${due}`
}

function projectSummary(f: Frame, width: number, rows: number): RenderElement {
  const { Box, Text, Link } = f.ui
  const project = state.projects.find(p => p.id === state.selectedProjectId)
  if (!project) return <Text dimColor>pick a project</Text>
  const facts = [project.state, percent(project.progress), project.health ?? '', project.lead ? `lead ${project.lead}` : '', project.targetDate ? `due ${monthDay(project.targetDate)}` : '']
  const current = currentMilestone(project.milestones)
  const href = safeHref(project.url)
  const lines: RenderElement[] = [
    <Text bold wrap="truncate-end">{truncateTo(project.name, width)}</Text>,
    textLine(f, width, facts.filter(Boolean).join(' · ')),
    ...project.milestones.slice(0, Math.max(0, rows - SUMMARY_FIXED_ROWS)).map(m => textLine(f, width, milestoneLine(m, m.id === current?.id), m.progress >= 1)),
  ]
  if (project.milestones.length === 0) lines.push(<Text dimColor>no milestones</Text>)
  lines.push(href ? <Link href={href} label="open in Linear" /> : <Text dimColor>{field(project.url) || 'no link'}</Text>)
  lines.push(<Text dimColor>Enter on a project lists its open issues</Text>)
  return <Box flexDirection="column" width={width}>{lines.slice(0, rows)}</Box>
}

function actionRow(f: Frame, issue: IssueDetail): RenderElement {
  const { Box, Button, Link, Text } = f.ui
  const href = safeHref(issue.url)
  // what a press sends may be more than the pane shows, so the size is said up front
  const sends = `sends ${Math.round(briefCharsOf(issue) / 100) / 10}k chars · ${Math.min(issue.comments.length, 5)} comments`
  return (
    <Box flexDirection="row" columnGap={1}>
      {ACTION_KINDS.map(kind => (
        <Button key={`linear:${kind}`} label={state.busy === kind ? `${kind}…` : kind} onPress={() => pressAction(f.engine, kind)} />
      ))}
      {href ? <Link href={href} label="open ↗" /> : <Text dimColor>{field(issue.url) || 'no link'}</Text>}
      <Text dimColor>{sends}</Text>
    </Box>
  )
}

function detailHead(f: Frame, issue: IssueDetail, width: number): RenderElement[] {
  const { Text } = f.ui
  const meta = [issue.state.name, issue.priorityLabel, issue.assignee ? `@${issue.assignee}` : 'unassigned', issue.milestone?.name ?? '', issue.project?.name ?? '']
  const facts = [issue.labels.join(', '), `updated ${relativeTime(issue.updatedAt, state.clock)}`, issue.branchName]
  return [
    <Text bold wrap="truncate-end">{truncateTo(`${issue.identifier} · ${issue.title}`, width)}</Text>,
    textLine(f, width, meta.filter(Boolean).join(' · '), false),
    textLine(f, width, facts.filter(Boolean).join(' · ')),
    actionRow(f, issue),
  ]
}

/** The description cut to `rows`, with a line naming what was cut. */
function descriptionRows(f: Frame, issue: IssueDetail, rows: number): RenderElement[] {
  const { Text, Code } = f.ui
  if (rows <= 0) return []
  const description = issue.description?.trim() ? sanitizeMarkdown(issue.description) : ''
  if (description === '') return [<Text dimColor>(no description)</Text>]
  // one row goes to the "n more" line, in case the text does not fit
  const { text, hidden } = firstLines(description, Math.max(1, rows - 1))
  const out: RenderElement[] = [<Code source={text} language="markdown" wrap="truncate-end" />]
  if (hidden > 0) out.push(<Text dimColor>{`… ${plural(hidden, 'more line')} · Enter opens the whole issue`}</Text>)
  return out
}

/** The detail cut to `rows`: head, the first lines of the description, the newest comments. */
function detailBudgeted(f: Frame, issue: IssueDetail, width: number, rows: number): RenderElement {
  const { Box } = f.ui
  const left = rows - DETAIL_HEAD_ROWS
  const comments = issue.comments.slice(-INLINE_COMMENTS)
  const commentRows = comments.length * INLINE_COMMENT_ROWS
  // comments only once the description still gets its minimum
  const withComments = left - MIN_DESCRIPTION_ROWS - 1 >= commentRows
  const out = [...detailHead(f, issue, width), ...descriptionRows(f, issue, left - (withComments ? commentRows : 0))]
  if (withComments) {
    for (const c of comments) {
      out.push(textLine(f, width, `${monthDay(c.createdAt)} · ${c.author}`))
      out.push(textLine(f, width, cleanText(c.body), false))
    }
  }
  return <Box flexDirection="column" width={width}>{out.slice(0, rows)}</Box>
}

/** The whole issue; the engine scrolls a docked pane. */
function detailFull(f: Frame, issue: IssueDetail, width: number): RenderElement {
  const { Box, Text, Code, Link } = f.ui
  const description = issue.description?.trim() ? sanitizeMarkdown(issue.description) : ''
  const out = detailHead(f, issue, width)
  out.push(description ? <Code source={description} language="markdown" wrap="wrap" /> : <Text dimColor>(no description)</Text>)
  if (issue.parent) out.push(textLine(f, width, `parent: ${issue.parent.identifier} · ${issue.parent.title}`))
  for (const child of issue.children) out.push(textLine(f, width, `child: ${child.identifier} · ${child.title} (${child.state})`))
  if (issue.comments.length) out.push(<Text bold>{plural(issue.comments.length, 'comment')}</Text>)
  for (const c of issue.comments) {
    out.push(textLine(f, width, `${monthDay(c.createdAt)} · ${c.author}`))
    out.push(<Code source={sanitizeMarkdown(c.body)} language="markdown" wrap="wrap" />)
  }
  for (const a of issue.attachments) {
    const href = safeHref(a.url)
    // the label names the real host: a title that reads like one link may point at another
    out.push(href ? <Link href={href} label={`${a.title || 'attachment'} (${new URL(href).hostname})`} /> : <Text dimColor>{field(a.url)}</Text>)
  }
  return <Box flexDirection="column" width={width}>{out}</Box>
}

/** The right column beside a docked issue list: the focused issue, cut to the rows. */
function detailPreview(f: Frame, width: number, rows: number): RenderElement {
  const { Text } = f.ui
  const issue = shownIssue()
  if (issue) return detailBudgeted(f, issue, width, rows)
  const loading = state.selectedIssue !== undefined && f.issues.length > 0
  return <Text dimColor>{loading ? `loading ${state.selectedIssue ?? ''}…` : 'pick an issue'}</Text>
}

/** The detail view: whole in a docked seat, which the engine scrolls; cut to the seat inline. */
function detailPage(f: Frame, width: number, rows: number): RenderElement {
  const { Text } = f.ui
  const issue = shownIssue()
  if (!issue) return <Text dimColor>{state.status.detail === 'loading' ? `loading ${state.selectedIssue ?? ''}…` : 'pick an issue'}</Text>
  return state.placement === 'dock' ? detailFull(f, issue, width) : detailBudgeted(f, issue, width, rows)
}

function promptEntry(f: Frame, width: number, kind: ActionKind): RenderElement[] {
  const { Box, Text, Button } = f.ui
  const template = templatePreview.get(kind) ?? DEFAULT_TEMPLATES[kind]
  const edited = template !== DEFAULT_TEMPLATES[kind]
  return [
    <Box flexDirection="row" columnGap={1}>
      <Text bold>{fit(kind, 8)}</Text>
      <Button key={`linear:edit:${kind}`} label="edit" dimColor onPress={() => pressEditPrompt(f.engine, kind)} />
      <Button key={`linear:reset:${kind}`} label="reset" dimColor onPress={() => resetPrompt(f.engine, kind)} />
      <Text dimColor>{edited ? 'edited' : 'default'}</Text>
    </Box>,
    textLine(f, width, `  ${firstLine(template)}`),
    textLine(f, width, `  ${plural(template.split('\n').length, 'line')}`),
  ]
}

function promptsView(f: Frame, width: number, rows: number): RenderElement {
  const { Box } = f.ui
  const placeholders = PLACEHOLDERS.map(name => `{${name}}`).join(' ')
  const out = [textLine(f, width, `the prompts the buttons send · placeholders: ${placeholders}`), ...ACTION_KINDS.flatMap(kind => promptEntry(f, width, kind))]
  return <Box flexDirection="column" width={width}>{out.slice(0, rows)}</Box>
}

function body(f: Frame): RenderElement {
  const { Box } = f.ui
  const { layout } = f
  if (state.view === 'prompts') return promptsView(f, layout.columns, layout.bodyRows)
  if (state.view === 'detail') return detailPage(f, layout.columns, layout.bodyRows)
  if (layout.mode !== 'dock') return listColumn(f, layout.columns)
  return (
    <Box flexDirection="row" columnGap={1}>
      {listColumn(f, layout.listColumns)}
      {state.view === 'projects' ? projectSummary(f, layout.detailColumns, layout.bodyRows) : detailPreview(f, layout.detailColumns, layout.bodyRows)}
    </Box>
  )
}

function paneView(f: Frame): RenderElement {
  const { Box } = f.ui
  return (
    <Box flexDirection="column" width={f.layout.columns}>
      {titleRow(f)}
      {buttonsRow(f)}
      {body(f)}
      {footerRow(f)}
    </Box>
  )
}

// ---- hooks -----------------------------------------------------------------

const bindHost = ($: EngineInterface): Host => ({
  now: () => $.clock.now(),
  after: (ms, fn) => $.clock.after(ms, fn),
  fetch: (url, init) => $.http.fetch(url, init),
  run: (argv, init) => $.process.run(argv, init),
  storeGet: key => $.store.get(key),
  storeSet: (key, value) => $.store.set(key, value),
  storeDelete: key => $.store.delete(key),
  invalidate: () => $.ui.invalidate('ui.render'),
  // the engine prefixes a log line with the plugin's name, as it does a command's reply
  uiLog: text => $.ui.log(text.replace(/^linear: /, '')),
  toast: text => $.ui.toast(text),
  openPane: pane => $.ui.open(pane),
  closePane: id => $.ui.close({ id }),
  cwd: () => $.session.cwd(),
  focus: key => $.ui.focus({ requestId: PANE_ID, key }),
  submit: text => $.prompt.submit({ text }),
  fill: text => $.prompt.fill({ text }),
})

let host: Host | undefined

export const register: Register = (on, options) => {
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    resetState()
    const engine = bindHost($)
    host = engine
    await $.command
      .register({
        name: PLUGIN,
        description: 'Your Linear projects, milestones and issues; plan, execute or product sends a prompt about one (linear)',
        argumentHint: ARGUMENT_HINT,
        immediate: true,
      })
      .catch(err => $.ui.log(`/${PLUGIN} not registered: ${safeMessage(err)}`))
    // a missing variable reads as undefined; the no-key footer says what to set
    const envKey = await $.env.get('LINEAR_API_KEY').catch(() => undefined)
    bindSource(engine, { apiKey: options.apiKey, teamId: options.teamId, envKey })
    if (await rehydrate(engine)) {
      // a plugin's own open waits undrawn below 144 columns; a /linear from the person always draws
      await openPaneQuietly(engine).catch(err => $.ui.log(`reopen at start failed: ${safeMessage(err)}`))
      void refreshCurrent(engine, false)
    }
    return r
  })

  // matchers are spelled as literals: the validator lists them off the source
  on('command.run', { command: 'linear' }, async ($, e, next) => {
    if (!host) return next(e)
    return runCommand(host, e.args)
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE_ID || !host || e.surface === 'mobile') return next(e)
    const { Box, Text, Button, Select, Link, Code } = $.ui.resolve(e)
    const layout = seatDrawn(e.props.placement, e.props.bodyColumns, e.props.scroll.bodyRows)
    if (layout.mode === 'narrow') return <Text dimColor>linear · widen the terminal to 40 columns</Text>
    return paneView({ ui: { Box, Text, Button, Select, Link, Code }, engine: host, layout, issues: filteredIssues() })
  })

  on('ui.close', { id: 'linear' }, async ($, e, next) => {
    const engine = host
    if (e.origin.kind === 'person' && engine && (await back(engine))) {
      reseat(engine)
      return { deny: 'back' }
    }
    const result = await next(e)
    const kept = result !== undefined && typeof result === 'object' && 'deny' in result && result.deny !== undefined
    if (!kept && engine) markClosed(engine)
    return result
  })

  on('ui.focus', { requestId: 'linear' }, async ($, e, next) => {
    const engine = host
    const key = e.element
    if (!engine || !key) return next(e)
    if (key.startsWith('row:')) {
      selectRow(engine, key)
      return next(e)
    }
    if (key === 'edge:up' || key === 'edge:down') {
      const landing = focusPastEdge(engine, key)
      if (landing) return next({ ...e, element: landing })
    }
    return next(e)
  })

  on('ui.scroll', { requestId: 'linear' }, async ($, e, next) => {
    if (!host || (state.view !== 'projects' && state.view !== 'issues')) return next(e)
    moveWindow(host, e.by)
    return {}
  })

  on('turn.start', async ($, e, next) => {
    turnStarted(e.text, e.turnId)
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId === undefined && host) turnCompleted(host, e.turnId)
    return next(e)
  })
}

