// linear: what `/linear <args>` means. Pure.

import { isActionKind } from './lib.ts'
import type { ActionKind } from './lib.ts'

export type Command =
  | { kind: 'open' }
  | { kind: 'close' }
  | { kind: 'refresh' }
  | { kind: 'mine' }
  | { kind: 'prompts' }
  | { kind: 'help' }
  | { kind: 'draft'; on: boolean | undefined }
  | { kind: 'issue'; ref: string }
  | { kind: 'set-prompt'; action: ActionKind; template: string }
  | { kind: 'reset-prompt'; action: ActionKind }
  | { kind: 'unknown'; text: string }

/** The hint drawn after the command name; `/linear help` lists the rest. */
export const ARGUMENT_HINT = '[ENG-123 | mine | refresh | prompts | draft on|off | help | close]'

export const HELP_TEXT = [
  '/linear · open the pane at the last view',
  '/linear ENG-123 · open one issue (eng 123, eng123 and an issue URL work too)',
  '/linear mine · my open issues across teams',
  '/linear refresh · fetch again now',
  '/linear prompts · the plan, execute and product templates',
  '/linear draft on|off · buttons fill the composer instead of sending',
  '/linear set-prompt <plan|execute|product> <text> · save an edited template',
  '/linear reset-prompt <plan|execute|product> · back to the default template',
  '/linear close · close the pane',
].join('\n')

const REF_RE = /^([a-z]{2,10})[\s-]?0{0,10}(\d{1,9})$/i
const URL_REF_RE = /linear\.app\/[^/]+\/issue\/([a-z]{2,10}-\d+)/i

/**
 * `eng 707`, `eng707`, `ENG0734`, `ENG-707` and an issue URL all name
 * `ENG-707`; anything else is not a reference.
 */
export function normalizeRef(text: string): string | undefined {
  const trimmed = text.trim()
  const fromUrl = URL_REF_RE.exec(trimmed)
  if (fromUrl?.[1]) return fromUrl[1].toUpperCase()
  const m = REF_RE.exec(trimmed)
  if (!m?.[1] || !m[2]) return undefined
  return `${m[1].toUpperCase()}-${Number(m[2])}`
}

const WORDS: Readonly<Record<string, Command>> = {
  '': { kind: 'open' },
  open: { kind: 'open' },
  close: { kind: 'close' },
  refresh: { kind: 'refresh' },
  mine: { kind: 'mine' },
  prompts: { kind: 'prompts' },
  help: { kind: 'help' },
}

export function parseArgs(args: string): Command {
  const text = args.trim()
  const [head = '', ...restWords] = text.split(/\s+/)
  const word = head.toLowerCase()
  const rest = text.slice(head.length).trim()
  const plain = WORDS[word]
  if (plain && (word === '' || rest === '')) return plain
  if (word === 'draft') return parseDraft(text, rest)
  if (word === 'set-prompt' || word === 'reset-prompt') return parsePromptCommand(word, text, rest, restWords[0])
  const ref = normalizeRef(text)
  if (ref) return { kind: 'issue', ref }
  return { kind: 'unknown', text }
}

function parseDraft(text: string, rest: string): Command {
  const value = rest.toLowerCase()
  if (value === '') return { kind: 'draft', on: undefined }
  if (value === 'on' || value === 'off') return { kind: 'draft', on: value === 'on' }
  return { kind: 'unknown', text }
}

function parsePromptCommand(word: 'set-prompt' | 'reset-prompt', text: string, rest: string, first: string | undefined): Command {
  const action = first?.toLowerCase()
  if (!isActionKind(action)) return { kind: 'unknown', text }
  if (word === 'reset-prompt') return { kind: 'reset-prompt', action }
  const template = rest.slice(first?.length ?? 0).trim()
  if (template === '') return { kind: 'unknown', text }
  return { kind: 'set-prompt', action, template }
}

