// linear: list windows and row budgets. Pure.

import { ACTION_KINDS } from './lib.ts'
import type { View } from './lib.ts'
import { clamp } from './text.ts'

// ---- list windows ----------------------------------------------------------

export type ListWindow = {
  /** The first and one-past-last index drawn. */
  start: number
  end: number
  /** Rows hidden above and below; a positive count draws an edge row. */
  above: number
  below: number
}

/**
 * The rows drawn from a list of `total` items in `room` rows, edge rows
 * included, starting near `offset`. The window never scrolls past the end and
 * always shows one item.
 */
export function windowOf(total: number, offset: number, room: number): ListWindow {
  if (total <= 0) return { start: 0, end: 0, above: 0, below: 0 }
  if (total <= room) return { start: 0, end: total, above: 0, below: 0 }
  let start = clamp(offset, 0, total - 1)
  let visible = Math.max(1, room - (start > 0 ? 1 : 0) - 1)
  if (start + visible >= total) {
    visible = Math.max(1, room - (start > 0 ? 1 : 0))
    start = Math.max(0, total - visible)
    if (start === 0) visible = Math.max(1, room)
  }
  const end = Math.min(total, start + visible)
  return { start, end, above: start, below: total - end }
}

// ---- the pane's seat -------------------------------------------------------

/** Below this many body columns the pane draws one hint row. */
export const MIN_COLUMNS = 40
/** The host docks a pane beside the transcript in fullscreen from this many terminal columns (asked)... */
export const HOST_DOCK_ASKED_COLUMNS = 110
/** ...and holds a pane the plugin opened on its own below this many. */
export const HOST_DOCK_UNASKED_COLUMNS = 144
export const DOCK_LIST_SHARE = 0.42
export const DOCK_LIST_MIN = 36
export const DOCK_LIST_MAX = 64
/** A docked body this wide draws the list beside a summary; narrower, one column. */
export const TWO_COLUMN_MIN = 2 * DOCK_LIST_MIN + 1
/** The rows the pane always draws: the title, the buttons, the footer. */
export const FRAME_ROWS = 3

export type Layout =
  | { mode: 'narrow' }
  | { mode: 'inline'; columns: number; bodyRows: number }
  | { mode: 'dock'; columns: number; bodyRows: number; listColumns: number; detailColumns: number }

export function layoutOf(placement: 'dock' | 'inline', columns: number, rows: number): Layout {
  if (columns < MIN_COLUMNS || rows < FRAME_ROWS + 1) return { mode: 'narrow' }
  const bodyRows = rows - FRAME_ROWS
  if (placement === 'inline' || columns < TWO_COLUMN_MIN) return { mode: 'inline', columns, bodyRows }
  const listColumns = clamp(Math.floor(columns * DOCK_LIST_SHARE), DOCK_LIST_MIN, DOCK_LIST_MAX)
  return { mode: 'dock', columns, bodyRows, listColumns, detailColumns: columns - listColumns - 1 }
}

/** The rows a list gets in `layout`: the body less the milestone picker when one is drawn. */
export const listRoomOf = (layout: Layout, hasPicker: boolean) =>
  layout.mode === 'narrow' ? 0 : Math.max(1, layout.bodyRows - (hasPicker ? 1 : 0))

export const MAX_INLINE_ROWS = 24
export const MIN_INLINE_ROWS = 6

/** The body rows the pane asks for inline: the list plus its frame, capped. */
export function rowsOf(view: View, count: number): number {
  const wanted =
    view === 'projects' ? count + FRAME_ROWS + 1 :
    view === 'issues' ? count + FRAME_ROWS + 2 :
    view === 'detail' ? MAX_INLINE_ROWS :
    ACTION_KINDS.length * 3 + FRAME_ROWS
  return clamp(wanted, MIN_INLINE_ROWS, MAX_INLINE_ROWS)
}

/** The first `max` lines of a markdown body, one row each when drawn truncated. */
export function firstLines(markdown: string, max: number): { text: string; hidden: number } {
  const lines = markdown.split('\n')
  const kept = lines.slice(0, Math.max(0, max))
  return { text: kept.join('\n'), hidden: Math.max(0, lines.length - kept.length) }
}

