// linear: the data types, the source seam, the guards and the milestone
// rules. No JSX and no import from 'claude-code', so `bun test` runs it
// without the early-access types. Text, arguments, windows and rows sit in
// their own modules beside this one.

import { field } from './text.ts'

// ---- data ------------------------------------------------------------------

export type Milestone = {
  id: string
  name: string
  targetDate: string | null
  sortOrder: number
  /** 0..1 as Linear reports it; 1 once every issue in it is done. */
  progress: number
}

export type Project = {
  id: string
  name: string
  state: string
  progress: number
  targetDate: string | null
  health: string | null
  url: string
  sortOrder: number
  lead: string | null
  milestones: Milestone[]
}

export type IssueState = { id: string; name: string; type: string }
export type Named = { id: string; name: string }

export type IssueSummary = {
  id: string
  identifier: string
  title: string
  /** Linear's scale: 0 none, 1 urgent, 2 high, 3 normal, 4 low. */
  priority: number
  priorityLabel: string
  updatedAt: string
  url: string
  state: IssueState
  assignee: string | null
  labels: string[]
  milestone: Named | null
  project: Named | null
}

export type IssueComment = { author: string; body: string; createdAt: string }
export type IssueRef = { identifier: string; title: string }

export type IssueDetail = IssueSummary & {
  description: string | null
  branchName: string
  createdAt: string
  estimate: number | null
  creator: string | null
  parent: IssueRef | null
  children: (IssueRef & { state: string })[]
  comments: IssueComment[]
  attachments: { title: string; url: string }[]
}

/** Which issues the list shows: one project's open issues, or mine across teams. */
export type Scope = { kind: 'project'; projectId: string } | { kind: 'mine' }

export type View = 'projects' | 'issues' | 'detail' | 'prompts'
export type ActionKind = 'plan' | 'execute' | 'product'
export const ACTION_KINDS: readonly ActionKind[] = ['plan', 'execute', 'product']

export const isActionKind = (value: unknown): value is ActionKind =>
  typeof value === 'string' && (ACTION_KINDS as readonly string[]).includes(value)

/**
 * The seam between the pane and a tracker. Linear is the only source today;
 * a Jira or GitHub source implements the same members.
 */
export type Source = {
  kind: 'linear'
  /** What an issue reference looks like once normalised (`CND-799`). */
  refPattern: RegExp
  projects(): Promise<{ teamName: string; projects: Project[] }>
  issues(scope: Scope): Promise<IssueSummary[]>
  issue(ref: string): Promise<IssueDetail>
}

export const scopeKey = (scope: Scope): string =>
  scope.kind === 'mine' ? 'mine' : `project:${scope.projectId}`

// ---- guards ----------------------------------------------------------------

export const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

export const asString = (value: unknown, fallback = ''): string =>
  typeof value === 'string' ? value : fallback

export const asNullableString = (value: unknown): string | null =>
  typeof value === 'string' ? value : null

export const asNumber = (value: unknown, fallback = 0): number =>
  typeof value === 'number' && Number.isFinite(value) ? value : fallback

export const nodesOf = (value: unknown): unknown[] => {
  if (!isRecord(value)) return []
  return Array.isArray(value.nodes) ? value.nodes : []
}

/** Linear names a person by `displayName` (the handle) or `name`; a bot by `name`. */
export const personName = (value: unknown): string | null => {
  if (!isRecord(value)) return null
  const name = asNullableString(value.displayName) ?? asNullableString(value.name)
  return name === null ? null : field(name)
}

// ---- cache guards -----------------------------------------------------------
// What comes back from `$.store` left the process; these check the shape of a
// cached record before it is drawn or put in a prompt.

const isStringArray = (value: unknown): value is string[] =>
  Array.isArray(value) && value.every(v => typeof v === 'string')

const isNullOrString = (value: unknown) => value === null || typeof value === 'string'

const isNamedOrNull = (value: unknown): value is Named | null =>
  value === null || (isRecord(value) && typeof value.id === 'string' && typeof value.name === 'string')

export const isMilestone = (value: unknown): value is Milestone =>
  isRecord(value) && typeof value.id === 'string' && typeof value.name === 'string' &&
  isNullOrString(value.targetDate) && typeof value.sortOrder === 'number' && typeof value.progress === 'number'

export const isProject = (value: unknown): value is Project =>
  isRecord(value) && typeof value.id === 'string' && typeof value.name === 'string' &&
  typeof value.state === 'string' && typeof value.progress === 'number' &&
  isNullOrString(value.targetDate) && isNullOrString(value.health) &&
  typeof value.url === 'string' && typeof value.sortOrder === 'number' && isNullOrString(value.lead) &&
  Array.isArray(value.milestones) && value.milestones.every(isMilestone)

export const isIssueSummary = (value: unknown): value is IssueSummary =>
  isRecord(value) && typeof value.id === 'string' && typeof value.identifier === 'string' &&
  typeof value.title === 'string' && typeof value.priority === 'number' &&
  typeof value.priorityLabel === 'string' && typeof value.updatedAt === 'string' &&
  typeof value.url === 'string' && isRecord(value.state) && typeof value.state.id === 'string' &&
  typeof value.state.name === 'string' && typeof value.state.type === 'string' &&
  isNullOrString(value.assignee) && isStringArray(value.labels) &&
  isNamedOrNull(value.milestone) && isNamedOrNull(value.project)

const isChild = (c: unknown) =>
  isRecord(c) && typeof c.identifier === 'string' && typeof c.title === 'string' && typeof c.state === 'string'
const isComment = (c: unknown) =>
  isRecord(c) && typeof c.author === 'string' && typeof c.body === 'string' && typeof c.createdAt === 'string'
const isAttachment = (a: unknown) => isRecord(a) && typeof a.title === 'string' && typeof a.url === 'string'

export function isIssueDetail(value: unknown): value is IssueDetail {
  if (!isIssueSummary(value)) return false
  const v = value as Record<string, unknown>
  return (
    isNullOrString(v.description) && typeof v.branchName === 'string' && typeof v.createdAt === 'string' &&
    (v.estimate === null || typeof v.estimate === 'number') && isNullOrString(v.creator) &&
    (v.parent === null || (isRecord(v.parent) && typeof v.parent.identifier === 'string' && typeof v.parent.title === 'string')) &&
    Array.isArray(v.children) && v.children.every(isChild) &&
    Array.isArray(v.comments) && v.comments.every(isComment) &&
    Array.isArray(v.attachments) && v.attachments.every(isAttachment)
  )
}

// ---- milestones ------------------------------------------------------------

/**
 * The milestone the project is on: among those still open (or, given the
 * open issues' milestone ids, those with open issues), the earliest target
 * date, then the lowest sort order. None when the project has no open one.
 */
export function currentMilestone(
  milestones: readonly Milestone[],
  openMilestoneIds?: ReadonlySet<string>,
): Milestone | undefined {
  const candidates = milestones.filter(m =>
    openMilestoneIds ? openMilestoneIds.has(m.id) : m.progress < 1,
  )
  return candidates.sort(compareMilestones)[0]
}

export function compareMilestones(a: Milestone, b: Milestone): number {
  if (a.targetDate && b.targetDate && a.targetDate !== b.targetDate) {
    return a.targetDate < b.targetDate ? -1 : 1
  }
  if (a.targetDate && !b.targetDate) return -1
  if (!a.targetDate && b.targetDate) return 1
  return a.sortOrder - b.sortOrder
}

/** Started projects first, then by Linear's own order. */
export function compareProjects(a: Project, b: Project): number {
  const rank = (p: Project) => (p.state === 'started' ? 0 : p.state === 'planned' ? 1 : 2)
  return rank(a) - rank(b) || a.sortOrder - b.sortOrder || a.name.localeCompare(b.name)
}

