// linear: the pane's state and everything that changes it. No JSX and only
// type imports from 'claude-code', so `bun test` drives it through a fake
// Host. `register.tsx` binds the real one and draws.

import type {
  HttpInit,
  HttpResponse,
  PaneOpenArgs,
  ProcessRunInit,
  ProcessRunResult,
  PromptFillResult,
  PromptSubmitResult,
  Timer,
} from 'claude-code'
import { ARGUMENT_HINT, HELP_TEXT, parseArgs } from './args.ts'
import type { Command } from './args.ts'
import { ACTION_KINDS, currentMilestone, isIssueDetail, isIssueSummary, isProject, isRecord, scopeKey } from './lib.ts'
import type { ActionKind, IssueDetail, IssueSummary, Project, Scope, Source, View } from './lib.ts'
import { RATE_LIMIT_FLOOR, errorKindOf, linearSource, messageOf } from './linear.ts'
import type { RateLimit } from './linear.ts'
import { layoutOf, listRoomOf, rowsOf, windowOf } from './layout.ts'
import type { Layout } from './layout.ts'
import { DEFAULT_TEMPLATES, briefSize, renderTemplate, setPromptCommand, templateProblem } from './prompts.ts'
import { field } from './text.ts'

/**
 * The slice of `$` the pane uses, bound once at `session.start`. Everything
 * here takes a `Host`, never `$`, so the tests run it against a fake.
 */
export type Host = {
  now: () => Promise<number>
  after: (ms: number, fn: () => void) => Timer
  fetch: (url: string, init: HttpInit) => Promise<HttpResponse>
  run: (argv: readonly string[], init?: ProcessRunInit) => Promise<ProcessRunResult>
  storeGet: (key: string) => Promise<unknown>
  storeSet: (key: string, value: unknown) => Promise<void>
  storeDelete: (key: string) => Promise<void>
  invalidate: () => void
  uiLog: (text: string) => void
  toast: (text: string) => void
  openPane: (pane: PaneOpenArgs) => Promise<void>
  closePane: (id: string) => Promise<void>
  cwd: () => Promise<string>
  focus: (key: string) => Promise<{ deny?: string }>
  submit: (text: string) => Promise<PromptSubmitResult>
  fill: (text: string) => Promise<PromptFillResult>
}

export const PLUGIN = 'linear'
export const PANE_ID = 'linear'
export const PANE_TITLE = 'Linear'

export const REDRAW_COALESCE_MS = 100
/** A `prompt.submit` or `prompt.fill` must leave the hook that asked for it; this is how long after. */
export const DEFER_MS = 50
export const POLL_MS = 60_000
export const POLL_BACKOFF_MS = 300_000
/** Each poll delay is scaled by 0.8..1.2 so sessions do not hit Linear in step. */
export const POLL_JITTER = 0.2
export const FAILURES_BEFORE_BACKOFF = 3
/** A pending action clears on the submitted turn's end, or after this. */
export const BUSY_TIMEOUT_MS = 300_000
export const PREVIEW_DEBOUNCE_MS = 300
export const GIT_TIMEOUT_MS = 3_000
export const DETAIL_CACHE_MAX = 20
export const ISSUES_CACHE_MAX = 10
export const PREVIEWS_MAX = 50
export const DETAIL_STALE_MS = 24 * 60 * 60 * 1000
export const RATE_LIMIT_PAUSE_MS = 60_000

export type Status = 'idle' | 'loading' | 'error'
type Loadable = 'projects' | 'issues' | 'detail'

// ---- state -----------------------------------------------------------------
// One hooks-module instance lives per Claude Code process, so this state is
// the session's. `session.start` fires again on a hot reload, resets it and
// reads back what `persisted()` names from `$.store`.

export type State = {
  isOpen: boolean
  view: View
  viewBeforePrompts: View
  teamName: string
  projects: Project[]
  scope: Scope | undefined
  milestoneFilter: string
  issues: IssueSummary[]
  detail: IssueDetail | undefined
  selectedProjectId: string | undefined
  selectedIssue: string | undefined
  projectOffset: number
  issueOffset: number
  status: Record<Loadable, Status>
  fetchedAt: Partial<Record<Loadable, number>>
  errorText: string
  rateLimitUntil: number
  failures: number
  busy: ActionKind | undefined
  /** The text the busy action submitted; its turn's start names the turn whose end releases the buttons. */
  busyText: string | undefined
  busyTurn: string | undefined
  draftMode: boolean
  placement: 'dock' | 'inline'
  /** The seat as last drawn, so the focus and wheel hooks window the list the way the draw did. */
  layout: Layout | undefined
  /** True from an open until the next draw: that draw sizes an inline seat to the rows the open asked for. */
  seatFresh: boolean
  clock: number
}

const initialState = (): State => ({
  isOpen: false,
  view: 'projects',
  viewBeforePrompts: 'projects',
  teamName: 'Linear',
  projects: [],
  scope: undefined,
  milestoneFilter: 'all',
  issues: [],
  detail: undefined,
  selectedProjectId: undefined,
  selectedIssue: undefined,
  projectOffset: 0,
  issueOffset: 0,
  status: { projects: 'idle', issues: 'idle', detail: 'idle' },
  fetchedAt: {},
  errorText: '',
  rateLimitUntil: 0,
  failures: 0,
  busy: undefined,
  busyText: undefined,
  busyTurn: undefined,
  draftMode: false,
  placement: 'inline',
  layout: undefined,
  seatFresh: false,
  clock: 0,
})

export let state: State = initialState()
let source: (Source & { rateLimit: () => RateLimit | undefined }) | undefined
let apiKey: string | undefined
const seq: Record<Loadable, number> = { projects: 0, issues: 0, detail: 0 }
const previews = new Map<string, IssueDetail>()
const briefSizes = new WeakMap<IssueDetail, number>()
/** What the prompts view shows: the stored templates, read when the view opens. */
export const templatePreview = new Map<ActionKind, string>()
type TimerName = 'redraw' | 'reopen' | 'focus' | 'poll' | 'action' | 'busy' | 'preview'
const timers = new Map<TimerName, Timer>()

/** Back to the start: what a hot reload does before it reads the store again. */
export function resetState() {
  cancelAll()
  state = initialState()
  source = undefined
  apiKey = undefined
  seq.projects = seq.issues = seq.detail = 0
  previews.clear()
  templatePreview.clear()
}

/** The part of the state that outlives the session, and nothing else. */
const persisted = () => ({
  view: state.view,
  scope: state.scope,
  milestoneFilter: state.milestoneFilter,
  selectedProjectId: state.selectedProjectId,
  selectedIssue: state.selectedIssue,
})

// ---- store -----------------------------------------------------------------

export const OPEN_KEY = 'open'
export const DRAFT_KEY = 'draftMode'
export const PROJECTS_KEY = 'cache:projects'
const DETAIL_INDEX_KEY = 'cache:issue-index'
const ISSUES_INDEX_KEY = 'cache:issues-index'
export const issuesKey = (s: Scope) => `cache:issues:${scopeKey(s)}`
export const detailKey = (ref: string) => `cache:issue:${ref}`
export const promptKey = (kind: ActionKind) => `prompt:${kind}`

function persist(engine: Host, key: string, value: unknown) {
  void engine.storeSet(key, value).catch(err => engine.uiLog(`${PLUGIN}: store write of ${key} failed: ${safeMessage(err)}`))
}

// a store miss is normal on first run; a read that rejects is treated as one, and logged
const stored = (engine: Host, key: string) =>
  engine.storeGet(key).catch(err => {
    engine.uiLog(`${PLUGIN}: store read of ${key} failed: ${safeMessage(err)}`)
    return undefined
  })

function saveOpen(engine: Host) {
  persist(engine, OPEN_KEY, state.isOpen ? persisted() : false)
}

export async function readTemplate(engine: Host, kind: ActionKind): Promise<string> {
  const value = await stored(engine, promptKey(kind))
  return typeof value === 'string' && value.trim() !== '' ? value : DEFAULT_TEMPLATES[kind]
}

/** Error text for the footer and the log: one cleaned line, never the key. */
export function safeMessage(error: unknown): string {
  let text = field(messageOf(error))
  if (apiKey && apiKey.length >= 8) text = text.split(apiKey).join('***')
  return text
}

// ---- timers ----------------------------------------------------------------

function cancel(name: TimerName) {
  timers.get(name)?.cancel()
  timers.delete(name)
}

function cancelAll() {
  for (const timer of timers.values()) timer.cancel()
  timers.clear()
}

/** Runs `fn` once, in place of any timer of the same name; the entry clears before it runs. */
function schedule(engine: Host, name: TimerName, ms: number, fn: () => void) {
  cancel(name)
  timers.set(
    name,
    engine.after(ms, () => {
      timers.delete(name)
      fn()
    }),
  )
}

export function redraw(engine: Host) {
  if (timers.has('redraw')) return
  // the footer's "refreshed n ago" reads the clock, so it moves with each draw
  schedule(engine, 'redraw', REDRAW_COALESCE_MS, () => void tick(engine).finally(() => engine.invalidate()))
}

export async function tick(engine: Host) {
  // a clock that does not answer leaves the last reading; nothing here needs it exact
  state.clock = await engine.now().catch(() => state.clock)
  return state.clock
}

// ---- selectors -------------------------------------------------------------

export function filteredIssues(): IssueSummary[] {
  if (state.milestoneFilter === 'all' || state.scope?.kind !== 'project') return state.issues
  return state.issues.filter(i => i.milestone?.id === state.milestoneFilter)
}

export const selectedProject = (): Project | undefined => state.projects.find(p => p.id === state.selectedProjectId)

export const listCount = () =>
  state.view === 'projects' ? state.projects.length : state.view === 'issues' ? filteredIssues().length : 0

/** Whether the issues view draws the milestone picker. */
export const hasPicker = () =>
  state.view === 'issues' && state.scope?.kind === 'project' && (selectedProject()?.milestones.length ?? 0) > 0

/** The rows the list has, as the last draw laid it out. */
export const listRoom = () => (state.layout ? listRoomOf(state.layout, hasPicker()) : rowsOf(state.view, listCount()))

export const isLoading = () => Object.values(state.status).includes('loading')

export const isPaused = (): boolean => {
  if (state.clock < state.rateLimitUntil) return true
  const limit = source?.rateLimit()
  return limit !== undefined && limit.remaining < RATE_LIMIT_FLOOR && state.clock < limit.resetAt
}

/** The issue drawn in the detail column: the detail, or the focused row's preview. */
export const shownIssue = (): IssueDetail | undefined =>
  state.view === 'detail' ? state.detail : state.selectedIssue ? previews.get(state.selectedIssue) : undefined

/** How big the brief a press sends is; measured once per issue. */
export function briefCharsOf(issue: IssueDetail): number {
  let size = briefSizes.get(issue)
  if (size === undefined) {
    size = briefSize(issue)
    briefSizes.set(issue, size)
  }
  return size
}

/** The element the focus ring should sit on for the current view. */
export function focusKey(): string | undefined {
  if (state.view === 'projects') return state.selectedProjectId ? `row:${state.selectedProjectId}` : undefined
  if (state.view === 'issues') return state.selectedIssue ? `row:${state.selectedIssue}` : undefined
  if (state.view === 'detail') return `linear:${ACTION_KINDS[0]}`
  return `linear:edit:${ACTION_KINDS[0]}`
}

// ---- pane ------------------------------------------------------------------

function paneArgs(focus: boolean): PaneOpenArgs {
  return {
    id: PANE_ID,
    title: PANE_TITLE,
    holdToasts: true,
    closeOnEscape: true,
    rows: rowsOf(state.view, listCount()),
    ...(focus ? { focus: true as const } : {}),
  }
}

/** Opens the pane on the person's ask: it takes the keyboard. */
export async function openPane(engine: Host) {
  await seat(engine, true)
}

/** Opens the pane on the plugin's own account (a session start): the keyboard stays where it is. */
export async function openPaneQuietly(engine: Host) {
  await seat(engine, false)
}

async function seat(engine: Host, focus: boolean) {
  state.seatFresh = true
  await engine.openPane(paneArgs(focus))
  state.isOpen = true
  saveOpen(engine)
  schedulePoll(engine)
  redraw(engine)
}

export async function closePane(engine: Host) {
  // a close that the host refuses leaves the pane; the state follows the host
  await engine.closePane(PANE_ID).catch(err => engine.uiLog(`${PLUGIN}: close failed: ${safeMessage(err)}`))
  markClosed(engine)
}

/** The pane is gone (closed by the plugin, the person or an unload): stop what only an open pane needs. */
export function markClosed(engine: Host) {
  state.isOpen = false
  cancel('poll')
  releaseBusy(engine)
  saveOpen(engine)
}

/**
 * Re-opens the pane so an inline seat takes the new view's rows, then puts the
 * ring on the view's element: a ring the person has moved does not follow an
 * `autoFocus`, so the plugin moves it once the new tree is drawn.
 */
export function reseat(engine: Host) {
  if (!state.isOpen) return
  schedule(engine, 'reopen', 0, () => {
    state.seatFresh = true
    void engine
      .openPane(paneArgs(true))
      .then(() =>
        schedule(engine, 'focus', REDRAW_COALESCE_MS + DEFER_MS, () => {
          const key = focusKey()
          // a refused focus (the person holds the keys elsewhere) is the person's call
          if (key) void engine.focus(key).catch(() => undefined)
        }),
      )
      .catch(err => engine.uiLog(`${PLUGIN}: reopen failed: ${safeMessage(err)}`))
  })
}

/**
 * A list that lands after its view opened empty had nothing for the ring to sit
 * on when `reseat` placed it; put the ring on the first row once it is drawn.
 */
function placeRingOnNewList(engine: Host, hadRing: boolean) {
  if (hadRing || !state.isOpen) return
  const key = focusKey()
  if (!key) return
  schedule(engine, 'focus', REDRAW_COALESCE_MS + DEFER_MS, () => {
    void engine.focus(key).catch(() => undefined)
  })
}

/** The seat as the render hook saw it; the draw that follows an open grows an inline seat to its request. */
export function seatDrawn(placement: 'dock' | 'inline', columns: number, bodyRows: number): Layout {
  state.placement = placement
  const grow = placement === 'inline' && (state.seatFresh || bodyRows === 0)
  state.seatFresh = false
  const rows = grow ? Math.max(bodyRows, rowsOf(state.view, listCount())) : bodyRows
  state.layout = layoutOf(placement, columns, rows)
  return state.layout
}

// ---- loading ---------------------------------------------------------------

function noteError(engine: Host, error: unknown) {
  const kind = errorKindOf(error)
  state.failures++
  if (kind === 'ratelimited') {
    const retryAt = (error as { retryAt?: number }).retryAt
    state.rateLimitUntil = retryAt && retryAt > state.clock ? retryAt : state.clock + RATE_LIMIT_PAUSE_MS
    state.errorText = 'rate limited by Linear'
    return
  }
  if (kind === 'no-key') {
    state.errorText = 'no Linear key · set LINEAR_API_KEY or /config → linear apiKey'
    return
  }
  if (kind === 'auth') {
    state.errorText = 'Linear rejected the key · /linear refresh retries'
    cancel('poll')
    return
  }
  state.errorText = safeMessage(error)
  if (kind === 'graphql' || kind === 'parse' || kind === undefined) {
    // what Linear or the parser said will not change on its own: no poll until a refresh
    cancel('poll')
    engine.uiLog(`${PLUGIN}: Linear answered: ${state.errorText}`)
  }
}

/**
 * One load: a sequence guard so a late answer is dropped, the status for the
 * footer, the clock, the failure count, and a redraw either way. `accept`
 * says whether the answer still belongs to what the pane shows.
 */
async function load<T>(engine: Host, what: Loadable, fetchIt: () => Promise<T>, accept: (value: T) => boolean): Promise<T | undefined> {
  if (!source) return undefined
  const mine = ++seq[what]
  state.status[what] = 'loading'
  redraw(engine)
  try {
    const value = await fetchIt()
    if (mine !== seq[what] || !accept(value)) return undefined
    state.fetchedAt[what] = await tick(engine)
    state.failures = 0
    state.errorText = ''
    return value
  } catch (error) {
    if (mine === seq[what]) noteError(engine, error)
    return undefined
  } finally {
    if (mine === seq[what]) {
      state.status[what] = state.errorText ? 'error' : 'idle'
      redraw(engine)
    }
  }
}

export async function loadProjects(engine: Host): Promise<boolean> {
  const result = await load(engine, 'projects', () => source!.projects(), () => true)
  if (!result) return false
  const hadRing = focusKey() !== undefined
  state.teamName = result.teamName
  state.projects = result.projects
  settleSelection()
  placeRingOnNewList(engine, hadRing)
  saveOpen(engine)
  persist(engine, PROJECTS_KEY, { teamName: state.teamName, projects: state.projects, at: state.fetchedAt.projects })
  return true
}

export async function loadIssues(engine: Host, target: Scope): Promise<boolean> {
  const stillShown = () => state.scope !== undefined && scopeKey(state.scope) === scopeKey(target)
  const result = await load(engine, 'issues', () => source!.issues(target), stillShown)
  if (!result) return false
  const hadRing = focusKey() !== undefined
  state.issues = result
  settleMilestoneFilter()
  settleSelection()
  placeRingOnNewList(engine, hadRing)
  saveOpen(engine)
  void cacheKeyed(engine, ISSUES_INDEX_KEY, issuesKey(target), { issues: state.issues, at: state.fetchedAt.issues }, ISSUES_CACHE_MAX)
  return true
}

/** The issue the detail view shows; a not-found answer says so in the footer. */
export async function loadDetail(engine: Host, ref: string): Promise<IssueDetail | undefined> {
  const result = await load(engine, 'detail', () => fetchIssue(engine, ref), () => state.selectedIssue === ref)
  if (result) state.detail = result
  else if (/not found/i.test(state.errorText)) state.errorText = `${ref}: not found in Linear`
  return result
}

/** An issue fetched for the docked preview: kept beside the list, never the footer's business. */
export async function loadPreview(engine: Host, ref: string): Promise<void> {
  try {
    await fetchIssue(engine, ref)
  } catch (error) {
    engine.uiLog(`${PLUGIN}: preview of ${ref} failed: ${safeMessage(error)}`)
  }
  redraw(engine)
}

async function fetchIssue(engine: Host, ref: string): Promise<IssueDetail> {
  if (!source) throw new Error('no source')
  const issue = await source.issue(ref)
  remember(ref, issue)
  void cacheKeyed(engine, DETAIL_INDEX_KEY, detailKey(ref), { issue, at: state.clock }, DETAIL_CACHE_MAX)
  return issue
}

/** Once the issues are in, the milestone picker lands on the project's current one. */
function settleMilestoneFilter() {
  const project = selectedProject()
  if (state.scope?.kind !== 'project' || !project) {
    state.milestoneFilter = 'all'
    return
  }
  const openIds = new Set(state.issues.flatMap(i => (i.milestone ? [i.milestone.id] : [])))
  if (state.milestoneFilter !== 'all' && openIds.has(state.milestoneFilter)) return
  state.milestoneFilter = currentMilestone(project.milestones, openIds)?.id ?? 'all'
  state.issueOffset = 0
}

/** The selection lands on the first row when it names nothing in the list; a draw never decides this. */
export function settleSelection() {
  if (!state.projects.some(p => p.id === state.selectedProjectId)) state.selectedProjectId = state.projects[0]?.id
  const list = filteredIssues()
  if (!list.some(i => i.identifier === state.selectedIssue)) state.selectedIssue = list[0]?.identifier
}

// ---- caches ----------------------------------------------------------------

/** Keeps the newest `PREVIEWS_MAX` details in memory for the docked preview. */
function remember(ref: string, issue: IssueDetail) {
  previews.delete(ref)
  previews.set(ref, issue)
  while (previews.size > PREVIEWS_MAX) {
    const oldest = previews.keys().next().value
    if (oldest === undefined) break
    previews.delete(oldest)
  }
}

/** Writes `key`, then keeps only the newest `max` keys listed under `indexKey`, deleting the rest. */
async function cacheKeyed(engine: Host, indexKey: string, key: string, value: unknown, max: number) {
  persist(engine, key, value)
  const index = await stored(engine, indexKey)
  const keys = (Array.isArray(index) ? index.filter((k): k is string => typeof k === 'string') : []).filter(k => k !== key)
  keys.push(key)
  while (keys.length > max) {
    const old = keys.shift()
    if (old) void engine.storeDelete(old).catch(err => engine.uiLog(`${PLUGIN}: store delete of ${old} failed: ${safeMessage(err)}`))
  }
  persist(engine, indexKey, keys)
}

// A cached record left the process: each read checks its shape and drops what does not fit.

async function readProjectsCache(engine: Host): Promise<boolean> {
  const value = await stored(engine, PROJECTS_KEY)
  if (!isRecord(value) || !Array.isArray(value.projects)) return false
  state.projects = value.projects.filter(isProject)
  state.teamName = typeof value.teamName === 'string' ? field(value.teamName) || state.teamName : state.teamName
  state.fetchedAt.projects = typeof value.at === 'number' ? value.at : undefined
  settleSelection()
  return true
}

async function readIssuesCache(engine: Host, target: Scope): Promise<boolean> {
  const value = await stored(engine, issuesKey(target))
  if (!isRecord(value) || !Array.isArray(value.issues)) return false
  state.issues = value.issues.filter(isIssueSummary)
  state.fetchedAt.issues = typeof value.at === 'number' ? value.at : undefined
  settleMilestoneFilter()
  settleSelection()
  return true
}

export async function readDetailCache(engine: Host, ref: string): Promise<IssueDetail | undefined> {
  const value = await stored(engine, detailKey(ref))
  if (!isRecord(value) || !isIssueDetail(value.issue)) return undefined
  const at = typeof value.at === 'number' ? value.at : 0
  if (state.clock - at > DETAIL_STALE_MS) return undefined
  remember(ref, value.issue)
  state.fetchedAt.detail = at
  return value.issue
}

/** Fills the view from the store so the pane draws before the network answers. */
async function warmCaches(engine: Host, all: boolean) {
  const { view, scope } = state
  if (all || (view === 'projects' && state.projects.length === 0)) await readProjectsCache(engine)
  if (scope && (all || ((view === 'issues' || view === 'detail') && state.issues.length === 0))) await readIssuesCache(engine, scope)
  if (view === 'detail' && state.selectedIssue && (all || !state.detail)) state.detail = await readDetailCache(engine, state.selectedIssue)
  if (view === 'prompts') void loadTemplatePreviews(engine)
}

/** The person's refresh: the buttons release, a pause Linear asked for ends, and the view fetches again. */
export async function pressRefresh(engine: Host): Promise<void> {
  releaseBusy(engine)
  state.rateLimitUntil = 0
  state.failures = 0
  await refreshCurrent(engine, true)
}

/** Fetches what the current view shows; `force` ignores the rate-limit floor but not a pause Linear asked for. */
export async function refreshCurrent(engine: Host, force: boolean): Promise<void> {
  await tick(engine)
  if (state.clock < state.rateLimitUntil) return
  if (!force && isPaused()) return
  const { view, scope, selectedIssue } = state
  if (view === 'projects' || state.projects.length === 0) await loadProjects(engine)
  if ((view === 'issues' || view === 'detail') && scope) await loadIssues(engine, scope)
  if (view === 'detail' && selectedIssue) await loadDetail(engine, selectedIssue)
}

function schedulePoll(engine: Host) {
  cancel('poll')
  if (!state.isOpen) return
  const base = state.failures >= FAILURES_BEFORE_BACKOFF ? POLL_BACKOFF_MS : POLL_MS
  const delay = Math.round(base * (1 - POLL_JITTER + Math.random() * 2 * POLL_JITTER))
  schedule(engine, 'poll', delay, () => void refreshCurrent(engine, false).finally(() => schedulePoll(engine)))
}

// ---- navigation ------------------------------------------------------------

function goTo(engine: Host, view: View) {
  state.view = view
  state.errorText = ''
  redraw(engine)
  saveOpen(engine)
  reseat(engine)
}

export async function showProjects(engine: Host) {
  goTo(engine, 'projects')
  if (state.projects.length === 0) await readProjectsCache(engine)
  void loadProjects(engine)
}

export async function showIssues(engine: Host, target: Scope) {
  const changed = !state.scope || scopeKey(state.scope) !== scopeKey(target)
  state.scope = target
  if (changed) {
    state.issues = []
    state.issueOffset = 0
    state.milestoneFilter = 'all'
    state.selectedIssue = undefined
    await readIssuesCache(engine, target)
  }
  goTo(engine, 'issues')
  void loadIssues(engine, target)
}

export async function showDetail(engine: Host, ref: string): Promise<boolean> {
  state.selectedIssue = ref
  state.detail = previews.get(ref) ?? (await readDetailCache(engine, ref))
  goTo(engine, 'detail')
  const loaded = await loadDetail(engine, ref)
  return loaded !== undefined || state.detail !== undefined
}

export function showPrompts(engine: Host) {
  if (state.view !== 'prompts') state.viewBeforePrompts = state.view
  void loadTemplatePreviews(engine)
  goTo(engine, 'prompts')
}

/** Esc and the back button: detail → issues → projects → closed. Returns false when there is nowhere to go. */
export async function back(engine: Host): Promise<boolean> {
  switch (state.view) {
    case 'prompts':
      goTo(engine, state.viewBeforePrompts)
      return true
    case 'detail':
      await (state.scope ? showIssues(engine, state.scope) : showProjects(engine))
      return true
    case 'issues':
      await showProjects(engine)
      return true
    case 'projects':
      return false
  }
}

/** The focus ring landed on a row: it is the selection; docked, its preview loads. */
export function selectRow(engine: Host, key: string) {
  const id = key.slice('row:'.length)
  if (state.view === 'projects') {
    if (state.projects.some(p => p.id === id) && state.selectedProjectId !== id) {
      state.selectedProjectId = id
      redraw(engine)
    }
    return
  }
  if (state.view !== 'issues' || state.selectedIssue === id || !filteredIssues().some(i => i.identifier === id)) return
  state.selectedIssue = id
  redraw(engine)
  if (state.placement === 'dock' && !previews.has(id)) {
    schedule(engine, 'preview', PREVIEW_DEBOUNCE_MS, () => {
      void readDetailCache(engine, id).then(cached => (cached ? redraw(engine) : loadPreview(engine, id)))
    })
  }
}

export function selectProject(engine: Host, id: string) {
  state.selectedProjectId = id
  void showIssues(engine, { kind: 'project', projectId: id })
}

export function pickMilestone(engine: Host, id: string) {
  state.milestoneFilter = id
  state.issueOffset = 0
  settleSelection()
  redraw(engine)
  saveOpen(engine)
}

/** Moves the list window by `by` rows; the selection stays where it is. */
export function moveWindow(engine: Host, by: number) {
  const total = listCount()
  const room = listRoom()
  if (state.view === 'projects') state.projectOffset = windowOf(total, state.projectOffset + by, room).start
  else if (state.view === 'issues') state.issueOffset = windowOf(total, state.issueOffset + by, room).start
  else return
  redraw(engine)
}

/**
 * The ring landed on an edge row: the window shifts one row and the ring
 * lands on the row that sat at that edge, which stays drawn after the shift.
 */
export function focusPastEdge(engine: Host, edge: 'edge:up' | 'edge:down'): string | undefined {
  const rows = state.view === 'projects' ? state.projects.map(p => `row:${p.id}`) : filteredIssues().map(i => `row:${i.identifier}`)
  const offset = state.view === 'projects' ? state.projectOffset : state.issueOffset
  const listWindow = windowOf(rows.length, offset, listRoom())
  const landing = edge === 'edge:up' ? rows[listWindow.start] : rows[listWindow.end - 1]
  moveWindow(engine, edge === 'edge:up' ? -1 : 1)
  if (landing) selectRow(engine, landing)
  return landing
}

// ---- actions ---------------------------------------------------------------

export function pressAction(engine: Host, kind: ActionKind) {
  const issue = state.detail
  if (!issue) {
    engine.toast('pick an issue first')
    return
  }
  if (state.busy) {
    engine.toast(`already sending the ${state.busy} prompt`)
    return
  }
  state.busy = kind
  redraw(engine)
  schedule(engine, 'action', DEFER_MS, () => {
    void sendAction(engine, kind, issue).catch(err => {
      releaseBusy(engine)
      engine.toast(`${kind}: ${safeMessage(err)}`)
    })
  })
}

async function promptFor(engine: Host, kind: ActionKind, issue: IssueDetail): Promise<string> {
  const [cwd, branch, template] = await Promise.all([
    // no directory to name is not a failure: the placeholder is left empty
    engine.cwd().catch(() => ''),
    currentBranch(engine),
    readTemplate(engine, kind),
  ])
  return renderTemplate(template, issue, { cwd, branch })
}

async function sendAction(engine: Host, kind: ActionKind, issue: IssueDetail) {
  const text = await promptFor(engine, kind, issue)
  if (state.draftMode) {
    const { isFilled } = await engine.fill(text)
    releaseBusy(engine)
    engine.toast(isFilled ? `${kind} prompt is in the composer · edit, then Enter` : 'the composer cannot take text now')
    return
  }
  const result = await engine.submit(text)
  if ('drop' in result && result.drop) {
    releaseBusy(engine)
    engine.toast(`${kind}: dropped · ${field(result.drop)}`)
    return
  }
  state.busyText = result.text
  engine.toast(`${kind} prompt sent for ${issue.identifier}`)
  schedule(engine, 'busy', BUSY_TIMEOUT_MS, () => releaseBusy(engine))
  redraw(engine)
}

/** The buttons take presses again. */
export function releaseBusy(engine: Host) {
  if (!state.busy) return
  state.busy = undefined
  state.busyText = undefined
  state.busyTurn = undefined
  cancel('busy')
  redraw(engine)
}

/** A turn started: when it carries the text the button sent, its end is what releases the buttons. */
export function turnStarted(text: string, turnId: string) {
  if (state.busy && state.busyText !== undefined && text === state.busyText) state.busyTurn = turnId
}

/** A main-loop turn ended: the buttons release if it was the submitted one (or none was matched). */
export function turnCompleted(engine: Host, turnId: string) {
  if (!state.busy) return
  if (state.busyTurn === undefined || state.busyTurn === turnId) releaseBusy(engine)
}

async function currentBranch(engine: Host): Promise<string> {
  try {
    const gitResult = await engine.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD'], { timeoutMs: GIT_TIMEOUT_MS })
    return gitResult.exitCode === 0 ? field(gitResult.stdout) : ''
  } catch {
    // no git, or no repository: the placeholder is left empty
    return ''
  }
}

export function pressEditPrompt(engine: Host, kind: ActionKind) {
  schedule(engine, 'action', DEFER_MS, () => {
    void readTemplate(engine, kind)
      .then(template => engine.fill(setPromptCommand(kind, template)))
      .then(({ isFilled }) =>
        engine.toast(isFilled ? `edit the ${kind} template in the composer, then Enter saves it` : 'the composer cannot take text now'),
      )
      .catch(err => engine.toast(`edit: ${safeMessage(err)}`))
  })
}

export function toggleDraft(engine: Host, on?: boolean) {
  state.draftMode = on ?? !state.draftMode
  persist(engine, DRAFT_KEY, state.draftMode)
  redraw(engine)
}

export async function loadTemplatePreviews(engine: Host) {
  for (const kind of ACTION_KINDS) templatePreview.set(kind, await readTemplate(engine, kind))
  redraw(engine)
}

export function resetPrompt(engine: Host, kind: ActionKind) {
  void engine.storeDelete(promptKey(kind)).catch(err => engine.uiLog(`${PLUGIN}: store delete of ${promptKey(kind)} failed: ${safeMessage(err)}`))
  templatePreview.set(kind, DEFAULT_TEMPLATES[kind])
  engine.toast(`${kind} template back to the default`)
  redraw(engine)
}

// ---- command ---------------------------------------------------------------

type Reply = { text?: string }
type Handler<K extends Command['kind']> = (engine: Host, command: Extract<Command, { kind: K }>) => Promise<Reply>

const ensureOpen = async (engine: Host) => {
  if (!state.isOpen) await openPane(engine)
}

const openCommand: Handler<'open'> = async engine => {
  if (!state.isOpen) {
    await tick(engine)
    await warmCaches(engine, false)
  }
  await openPane(engine)
  void refreshCurrent(engine, true)
  return {}
}

const closeCommand: Handler<'close'> = async engine => {
  if (!state.isOpen) return { text: 'the pane is closed' }
  await closePane(engine)
  return { text: 'pane closed · /linear reopens it' }
}

const refreshCommand: Handler<'refresh'> = async engine => {
  await ensureOpen(engine)
  void pressRefresh(engine)
  return {}
}

const mineCommand: Handler<'mine'> = async engine => {
  await tick(engine)
  await ensureOpen(engine)
  state.selectedProjectId = undefined
  await showIssues(engine, { kind: 'mine' })
  return {}
}

/** The issue is resolved before the view moves, so a miss leaves the pane where it was. */
const issueCommand: Handler<'issue'> = async (engine, command) => {
  await tick(engine)
  await ensureOpen(engine)
  const known = previews.get(command.ref) ?? (await readDetailCache(engine, command.ref))
  if (!known) {
    try {
      await fetchIssue(engine, command.ref)
    } catch (error) {
      const kind = errorKindOf(error)
      const text = kind === 'graphql' || kind === 'parse' ? `${command.ref}: not found in Linear` : safeMessage(error)
      return { text }
    }
  }
  await showDetail(engine, command.ref)
  return {}
}

const promptsCommand: Handler<'prompts'> = async engine => {
  await ensureOpen(engine)
  showPrompts(engine)
  return {}
}

const helpCommand: Handler<'help'> = async () => ({ text: HELP_TEXT })

const draftCommand: Handler<'draft'> = async (engine, command) => {
  toggleDraft(engine, command.on)
  return { text: state.draftMode ? 'draft on · the buttons fill the composer' : 'draft off · the buttons send the prompt' }
}

const setPromptCommandHandler: Handler<'set-prompt'> = async (engine, command) => {
  const problem = templateProblem(command.template)
  if (problem) return { text: `${command.action} template not saved · ${problem}` }
  try {
    await engine.storeSet(promptKey(command.action), command.template)
  } catch (err) {
    return { text: `${command.action} template not saved · ${safeMessage(err)}` }
  }
  templatePreview.set(command.action, command.template)
  redraw(engine)
  const lines = command.template.split('\n').length
  return { text: `${command.action} template saved (${lines} lines) · /linear reset-prompt ${command.action} restores the default` }
}

const resetPromptCommand: Handler<'reset-prompt'> = async (engine, command) => {
  resetPrompt(engine, command.action)
  return { text: `${command.action} template back to the default` }
}

const unknownCommand: Handler<'unknown'> = async (_engine, command) => ({
  text: `"${field(command.text, 60)}" is not understood · /linear ${ARGUMENT_HINT} · /linear help lists everything`,
})

export async function runCommand(engine: Host, args: string): Promise<Reply> {
  const command = parseArgs(args)
  switch (command.kind) {
    case 'open': return openCommand(engine, command)
    case 'close': return closeCommand(engine, command)
    case 'refresh': return refreshCommand(engine, command)
    case 'mine': return mineCommand(engine, command)
    case 'issue': return issueCommand(engine, command)
    case 'prompts': return promptsCommand(engine, command)
    case 'help': return helpCommand(engine, command)
    case 'draft': return draftCommand(engine, command)
    case 'set-prompt': return setPromptCommandHandler(engine, command)
    case 'reset-prompt': return resetPromptCommand(engine, command)
    case 'unknown': return unknownCommand(engine, command)
    default: {
      const never: never = command
      return never
    }
  }
}

// ---- session start ---------------------------------------------------------

export type SessionOptions = { apiKey?: unknown; teamId?: unknown; envKey: string | undefined }

/** The key from the plugin's config, else the environment; a header value may not carry a line break. */
const keyOf = (value: unknown) => (typeof value === 'string' ? value.replace(/[\r\n]/g, '').trim() : '')

export function bindSource(engine: Host, options: SessionOptions) {
  apiKey = keyOf(options.apiKey) || keyOf(options.envKey) || undefined
  source = linearSource({
    fetch: (url, init) => engine.fetch(url, init),
    after: (ms, fn) => engine.after(ms, fn),
    key: () => apiKey,
    teamId: keyOf(options.teamId),
  })
}

const isView = (value: unknown): value is View => value === 'projects' || value === 'issues' || value === 'detail' || value === 'prompts'

const isScope = (value: unknown): value is Scope =>
  isRecord(value) && (value.kind === 'mine' || (value.kind === 'project' && typeof value.projectId === 'string'))

/** Reads the open state back from the store; true when the pane was open. */
export async function rehydrate(engine: Host): Promise<boolean> {
  await tick(engine)
  state.draftMode = (await stored(engine, DRAFT_KEY)) === true
  const storedView = await stored(engine, OPEN_KEY)
  if (!isRecord(storedView)) return false
  state.view = isView(storedView.view) ? storedView.view : 'projects'
  state.scope = isScope(storedView.scope) ? storedView.scope : undefined
  state.milestoneFilter = typeof storedView.milestoneFilter === 'string' ? storedView.milestoneFilter : 'all'
  state.selectedProjectId = typeof storedView.selectedProjectId === 'string' ? storedView.selectedProjectId : undefined
  state.selectedIssue = typeof storedView.selectedIssue === 'string' ? storedView.selectedIssue : undefined
  if ((state.view === 'issues' || state.view === 'detail') && !state.scope) state.view = 'projects'
  if (state.view === 'detail' && !state.selectedIssue) state.view = 'issues'
  await warmCaches(engine, true)
  return true
}

