// linear: one list row as text, exactly as wide as asked. Pure.

import { currentMilestone } from './lib.ts'
import type { IssueSummary, Project } from './lib.ts'
import { cleanText, fit, percent, priorityGlyph } from './text.ts'

export const MARKER = '▸'

/** Fixed columns of a row: the marker, then each named part, one space between. */
const MARKER_COLS = 1
const GAP = 1
const ID_COLS = 8
const GLYPH_COLS = 3
const STATE_COLS = 12
const PROJECT_STATE_COLS = 9
const PERCENT_COLS = 4
const NAME_COLS_MAX = 30
/** Rows narrower than these drop parts, widest first. */
const ISSUE_FULL_MIN = 56
const ISSUE_MID_MIN = 30
const PROJECT_FULL_MIN = 60
const PROJECT_MID_MIN = 36

/** The cells left for the last part after `parts` fixed columns and the gaps between everything. */
const restOf = (width: number, parts: readonly number[]) =>
  width - MARKER_COLS - parts.reduce((n, p) => n + p, 0) - GAP * (parts.length + 1)

/** `▸ CND-799 !!  In Progress  title…`, exactly `width` cells. */
export function issueRow(issue: IssueSummary, width: number, selected: boolean): string {
  const marker = selected ? MARKER : ' '
  const id = fit(issue.identifier, ID_COLS)
  const glyph = fit(priorityGlyph(issue.priority), GLYPH_COLS)
  const title = cleanText(issue.title)
  if (width >= ISSUE_FULL_MIN) {
    const state = fit(cleanText(issue.state.name), STATE_COLS)
    return `${marker} ${id} ${glyph} ${state} ${fit(title, restOf(width, [ID_COLS, GLYPH_COLS, STATE_COLS]))}`
  }
  if (width >= ISSUE_MID_MIN) return `${marker} ${id} ${glyph} ${fit(title, restOf(width, [ID_COLS, GLYPH_COLS]))}`
  return `${marker} ${fit(`${issue.identifier} ${title}`, restOf(width, []))}`
}

/** `▸ Product Experience   started  45%  › Milestone`, exactly `width` cells. */
export function projectRow(project: Project, width: number, selected: boolean): string {
  const marker = selected ? MARKER : ' '
  const name = cleanText(project.name)
  const milestone = currentMilestone(project.milestones)
  const tail = milestone ? `› ${cleanText(milestone.name)}` : ''
  const state = fit(project.state, PROJECT_STATE_COLS)
  const done = fit(percent(project.progress), PERCENT_COLS)
  if (width >= PROJECT_FULL_MIN) {
    // the name takes up to its cap; the milestone gets what is left
    const nameCols = Math.min(NAME_COLS_MAX, restOf(width, [PROJECT_STATE_COLS, PERCENT_COLS]) - 16)
    return `${marker} ${fit(name, nameCols)} ${state} ${done} ${fit(tail, restOf(width, [nameCols, PROJECT_STATE_COLS, PERCENT_COLS]))}`
  }
  if (width >= PROJECT_MID_MIN) return `${marker} ${fit(name, restOf(width, [PROJECT_STATE_COLS, PERCENT_COLS]))} ${state} ${done}`
  return `${marker} ${fit(name, restOf(width, []))}`
}

