// linear: text from the tracker, made safe for a terminal row and a prompt.
// Sanitisers, cell widths, cutting and padding, small formatters. Pure.

/**
 * What no text from the tracker may carry: C0, DEL and C1 controls, the line
 * and paragraph separators, bidi overrides and isolates, zero-width and
 * variation characters, and the Unicode tag block (U+E0000..E007F as a
 * surrogate pair), all invisible in a terminal and verbatim in a prompt.
 */
const CONTROL_RE = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F-\u009F\u2028\u2029]/g
const INVISIBLE_RE = /[\u061C\u200B-\u200F\u202A-\u202E\u2066-\u2069\uFEFF\uFE00-\uFE0F]|\uDB40[\uDC00-\uDC7F]/g

/** A `Code` element takes this much at most. */
export const MAX_CODE_CHARS = 10_000
/** Every one-line value drawn or put in a prompt is cut to this. */
export const MAX_FIELD_CHARS = 200
/** A `Link` href is at most this long. */
export const MAX_HREF_CHARS = 2048

/** One-line text: control and invisible characters out, whitespace runs folded to a space. */
export function cleanText(text: string): string {
  return text.replace(CONTROL_RE, '').replace(INVISIBLE_RE, '').replace(/\s+/g, ' ').trim()
}

/** Markdown for a `Code` element: only tab and newline as control characters, capped. */
export function sanitizeMarkdown(text: string, max = MAX_CODE_CHARS): string {
  const normalised = text.replace(/\r\n?/g, '\n').replace(CONTROL_RE, '').replace(INVISIBLE_RE, '')
  return normalised.length > max ? `${normalised.slice(0, max - 1)}…` : normalised
}

/** A one-line value from the tracker: cleaned and capped. */
export const field = (text: string | null | undefined, max = MAX_FIELD_CHARS) =>
  truncateTo(cleanText(text ?? ''), max)

/** A `Link` href the engine accepts: https only (a tracker link never points at localhost), ASCII, spelled by URL. */
export function safeHref(text: string): string | undefined {
  try {
    const url = new URL(text.trim())
    if (url.protocol !== 'https:') return undefined
    if (url.username || url.password) return undefined
    const href = url.href
    if (href.length > MAX_HREF_CHARS || /[^\x21-\x7E]/.test(href)) return undefined
    return href
  } catch {
    // not a URL at all: the caller draws the text dim instead of a link
    return undefined
  }
}

// ---- cells -------------------------------------------------------------------

/** Terminal cells one character takes: two for East Asian wide and emoji, none for a combining mark. */
export function cellWidth(char: string): number {
  const cp = char.codePointAt(0) ?? 0
  if (cp < 0x20) return 0
  if (cp >= 0x0300 && cp <= 0x036f) return 0
  if (
    (cp >= 0x1100 && cp <= 0x115f) || (cp >= 0x2e80 && cp <= 0xa4cf) || (cp >= 0xac00 && cp <= 0xd7a3) ||
    (cp >= 0xf900 && cp <= 0xfaff) || (cp >= 0xfe30 && cp <= 0xfe4f) || (cp >= 0xff00 && cp <= 0xff60) ||
    (cp >= 0xffe0 && cp <= 0xffe6) || (cp >= 0x1f300 && cp <= 0x1f64f) || (cp >= 0x1f900 && cp <= 0x1f9ff) ||
    (cp >= 0x20000 && cp <= 0x3fffd)
  ) {
    return 2
  }
  return 1
}

/** The cells `text` takes on one row. */
export const cellsOf = (text: string) => [...text].reduce((n, ch) => n + cellWidth(ch), 0)

/** `text` cut to at most `width` cells; a cut ends in an ellipsis. */
export function truncateTo(text: string, width: number): string {
  if (cellsOf(text) <= width) return text
  if (width <= 1) return '…'
  let out = ''
  let used = 0
  for (const ch of text) {
    const w = cellWidth(ch)
    if (used + w > width - 1) break
    out += ch
    used += w
  }
  return out + '…'
}

/** `text` cut or padded to exactly `width` cells. */
export function fit(text: string, width: number): string {
  if (width <= 0) return ''
  const cut = truncateTo(text, width)
  return cut + ' '.repeat(Math.max(0, width - cellsOf(cut)))
}

// ---- formatters --------------------------------------------------------------

export const PRIORITY_GLYPHS: readonly string[] = ['·', '!!!', '!!', '!', '↓']
export const priorityGlyph = (priority: number) => PRIORITY_GLYPHS[priority] ?? '·'

export function relativeTime(iso: string, now: number): string {
  const then = Date.parse(iso)
  if (!Number.isFinite(then)) return ''
  const seconds = Math.max(0, Math.round((now - then) / 1000))
  if (seconds < 60) return `${seconds}s ago`
  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return `${minutes} min ago`
  const hours = Math.round(minutes / 60)
  if (hours < 48) return `${hours} h ago`
  return `${Math.round(hours / 24)} d ago`
}

/** `Sep 15`, read in UTC so a midnight timestamp does not slip a day west of it. */
export const monthDay = (iso: string) => {
  const d = new Date(iso)
  if (!Number.isFinite(d.getTime())) return ''
  return `${d.toLocaleString('en-US', { month: 'short', timeZone: 'UTC' })} ${d.getUTCDate()}`
}

export const clamp = (value: number, min: number, max: number) => Math.min(max, Math.max(min, value))

export const percent = (fraction: number) => `${Math.round(clamp(fraction, 0, 1) * 100)}%`

export const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

