// linear: the GraphQL client behind the Source seam. The fetch and the clock
// are injected so the client runs under `bun test` with a fake of each.

import { asNullableString, asNumber, asString, compareProjects, isRecord, nodesOf, personName } from './lib.ts'
import type { IssueComment, IssueDetail, IssueSummary, Milestone, Project, Scope, Source } from './lib.ts'
import { MAX_HREF_CHARS, field } from './text.ts'

export const LINEAR_URL = 'https://api.linear.app/graphql'
export const DEFAULT_TIMEOUT_MS = 10_000
export const PAGE_SIZE = 50
export const MAX_PAGES = 5
/** Polling pauses when fewer requests than this remain in the hour. */
export const RATE_LIMIT_FLOOR = 50

export type HttpLike = {
  status: number
  ok: boolean
  headers: Record<string, string>
  text: string
}
export type FetchLike = (
  url: string,
  init: { method: string; headers: Record<string, string>; body: string },
) => Promise<HttpLike>
/** A one-shot timer the client can cancel once the request wins the race. */
export type AfterLike = (ms: number, fn: () => void) => { cancel: () => void }

export const messageOf = (error: unknown): string =>
  error instanceof Error ? error.message : String(error)

export type ErrorKind = 'no-key' | 'auth' | 'ratelimited' | 'timeout' | 'network' | 'graphql' | 'parse'

export class LinearError extends Error {
  readonly kind: ErrorKind
  /** When a rate-limited call may be retried, epoch milliseconds. */
  readonly retryAt: number | undefined
  constructor(kind: ErrorKind, message: string, retryAt?: number) {
    super(message)
    this.kind = kind
    this.retryAt = retryAt
  }
}

export const errorKindOf = (error: unknown): ErrorKind | undefined =>
  error instanceof LinearError ? error.kind : undefined

export type RateLimit = { remaining: number; resetAt: number }

export type ClientOptions = {
  fetch: FetchLike
  after: AfterLike
  /** Read at each call so a key set in `/config` after load is picked up. */
  key: () => string | undefined
  /** The team whose projects are listed; empty, the workspace's first team. */
  teamId: string
  timeoutMs?: number
  onRateLimit?: (limit: RateLimit) => void
}

// ---- queries ---------------------------------------------------------------

const PROJECT_FIELDS = `id name state progress targetDate health url sortOrder
        lead { name displayName }
        projectMilestones(first: 10) { nodes { id name targetDate sortOrder progress } }`

export const PROJECTS_QUERY = `query Projects($teamId: String!) {
  team(id: $teamId) {
    name
    projects(first: 25, filter: { state: { nin: ["completed", "canceled"] } }) {
      nodes { ${PROJECT_FIELDS} }
    }
  }
}`

/** Without a configured team: the workspace's first team. */
export const FIRST_TEAM_PROJECTS_QUERY = `query FirstTeamProjects {
  teams(first: 1) {
    nodes {
      name
      projects(first: 25, filter: { state: { nin: ["completed", "canceled"] } }) {
        nodes { ${PROJECT_FIELDS} }
      }
    }
  }
}`

export const ISSUES_QUERY = `query Issues($filter: IssueFilter!, $after: String) {
  issues(
    filter: $filter
    sort: [{ priority: { order: Descending, noPriorityFirst: false } }, { updatedAt: { order: Descending } }]
    first: ${PAGE_SIZE}
    after: $after
  ) {
    pageInfo { hasNextPage endCursor }
    nodes {
      id identifier title priority priorityLabel updatedAt url
      state { id name type }
      assignee { name displayName }
      labels(first: 10) { nodes { name } }
      projectMilestone { id name }
      project { id name }
    }
  }
}`

export const ISSUE_QUERY = `query Issue($id: String!) {
  issue(id: $id) {
    id identifier title description priority priorityLabel estimate createdAt updatedAt url branchName
    state { id name type }
    assignee { name displayName }
    creator { name displayName }
    labels(first: 10) { nodes { name } }
    projectMilestone { id name }
    project { id name }
    parent { identifier title }
    children(first: 20) { nodes { identifier title state { name } } }
    comments(first: 10) { nodes { body createdAt user { name displayName } botActor { name } } }
    attachments(first: 20) { nodes { title url } }
  }
}`

const OPEN_STATES = { state: { type: { nin: ['completed', 'canceled'] } } }

export function issueFilterOf(scope: Scope): Record<string, unknown> {
  if (scope.kind === 'mine') return { assignee: { isMe: { eq: true } }, ...OPEN_STATES }
  return { project: { id: { eq: scope.projectId } }, ...OPEN_STATES }
}

// ---- parsers ---------------------------------------------------------------
// Every one-line string is cleaned and capped as it is parsed, so nothing
// downstream has to remember to; markdown bodies are cleaned where drawn.

function parseMilestone(value: unknown): Milestone | undefined {
  if (!isRecord(value) || typeof value.id !== 'string' || typeof value.name !== 'string') return undefined
  return {
    id: value.id,
    name: field(value.name),
    targetDate: asNullableString(value.targetDate),
    sortOrder: asNumber(value.sortOrder),
    progress: asNumber(value.progress),
  }
}

function parseProject(value: unknown): Project | undefined {
  if (!isRecord(value) || typeof value.id !== 'string') return undefined
  return {
    id: value.id,
    name: field(asString(value.name)),
    state: field(asString(value.state, 'backlog')),
    progress: asNumber(value.progress),
    targetDate: asNullableString(value.targetDate),
    health: value.health === null || value.health === undefined ? null : field(asString(value.health)),
    url: field(asString(value.url), MAX_HREF_CHARS),
    sortOrder: asNumber(value.sortOrder),
    lead: personName(value.lead),
    milestones: nodesOf(value.projectMilestones).flatMap(m => parseMilestone(m) ?? []),
  }
}

function parseTeam(team: unknown): { teamName: string; projects: Project[] } {
  if (!isRecord(team)) throw new LinearError('parse', 'no team in the answer')
  const projects = nodesOf(team.projects).flatMap(p => parseProject(p) ?? [])
  return { teamName: field(asString(team.name, 'Linear')) || 'Linear', projects: projects.sort(compareProjects) }
}

export function parseProjects(data: unknown): { teamName: string; projects: Project[] } {
  if (!isRecord(data)) throw new LinearError('parse', 'no team in the answer')
  return parseTeam(data.team ?? nodesOf(data.teams)[0])
}

const named = (value: unknown) =>
  isRecord(value) && typeof value.id === 'string' ? { id: value.id, name: field(asString(value.name)) } : null

function parseIssueSummary(value: unknown): IssueSummary | undefined {
  if (!isRecord(value) || typeof value.id !== 'string' || typeof value.identifier !== 'string') return undefined
  const state = isRecord(value.state) ? value.state : {}
  return {
    id: value.id,
    identifier: field(value.identifier, 32),
    title: field(asString(value.title)),
    priority: asNumber(value.priority),
    priorityLabel: field(asString(value.priorityLabel), 32),
    updatedAt: field(asString(value.updatedAt), 40),
    url: field(asString(value.url), MAX_HREF_CHARS),
    state: { id: asString(state.id), name: field(asString(state.name), 64), type: field(asString(state.type), 32) },
    assignee: personName(value.assignee),
    labels: nodesOf(value.labels).flatMap(l => (isRecord(l) && typeof l.name === 'string' ? [field(l.name, 64)] : [])),
    milestone: named(value.projectMilestone),
    project: named(value.project),
  }
}

export function parseIssuesPage(data: unknown): { issues: IssueSummary[]; after: string | undefined } {
  if (!isRecord(data) || !isRecord(data.issues)) throw new LinearError('parse', 'no issues in the answer')
  const page = isRecord(data.issues.pageInfo) ? data.issues.pageInfo : {}
  const after = page.hasNextPage === true && typeof page.endCursor === 'string' ? page.endCursor : undefined
  return { issues: nodesOf(data.issues).flatMap(i => parseIssueSummary(i) ?? []), after }
}

function parseComments(value: unknown): IssueComment[] {
  const comments = nodesOf(value).flatMap(c => {
    if (!isRecord(c)) return []
    const bot = isRecord(c.botActor) ? asNullableString(c.botActor.name) : null
    const author = personName(c.user) ?? (bot === null ? null : field(bot)) ?? 'someone'
    return [{ author, body: asString(c.body), createdAt: field(asString(c.createdAt), 40) }]
  })
  return comments.sort((a, b) => (a.createdAt < b.createdAt ? -1 : a.createdAt > b.createdAt ? 1 : 0))
}

const parseChildren = (value: unknown) =>
  nodesOf(value).flatMap(c =>
    isRecord(c) && typeof c.identifier === 'string'
      ? [{ identifier: field(c.identifier, 32), title: field(asString(c.title)), state: isRecord(c.state) ? field(asString(c.state.name), 64) : '' }]
      : [],
  )

const parseAttachments = (value: unknown) =>
  nodesOf(value).flatMap(a =>
    isRecord(a) && typeof a.url === 'string' ? [{ title: field(asString(a.title)), url: field(a.url, MAX_HREF_CHARS) }] : [],
  )

export function parseIssue(data: unknown): IssueDetail {
  if (!isRecord(data) || !isRecord(data.issue)) throw new LinearError('parse', 'not found in Linear')
  const raw = data.issue
  const summary = parseIssueSummary(raw)
  if (!summary) throw new LinearError('parse', 'not found in Linear')
  const parent = isRecord(raw.parent) && typeof raw.parent.identifier === 'string'
    ? { identifier: field(raw.parent.identifier, 32), title: field(asString(raw.parent.title)) }
    : null
  return {
    ...summary,
    description: asNullableString(raw.description),
    branchName: field(asString(raw.branchName)),
    createdAt: field(asString(raw.createdAt), 40),
    estimate: typeof raw.estimate === 'number' ? raw.estimate : null,
    creator: personName(raw.creator),
    parent,
    children: parseChildren(raw.children),
    comments: parseComments(raw.comments),
    attachments: parseAttachments(raw.attachments),
  }
}

// ---- transport -------------------------------------------------------------

export function rateLimitOf(headers: Record<string, string>): RateLimit | undefined {
  const remaining = Number(headers['x-ratelimit-requests-remaining'])
  const resetAt = Number(headers['x-ratelimit-requests-reset'])
  if (!Number.isFinite(remaining) || !Number.isFinite(resetAt)) return undefined
  return { remaining, resetAt }
}

function firstGraphqlError(errors: unknown): { message: string; code: string | undefined } | undefined {
  if (!Array.isArray(errors) || errors.length === 0) return undefined
  const first = errors[0]
  if (!isRecord(first)) return { message: 'unknown error', code: undefined }
  const ext = isRecord(first.extensions) ? first.extensions : {}
  return { message: asString(first.message, 'unknown error'), code: asNullableString(ext.code) ?? undefined }
}

/** The request, raced against a timer the request cancels when it wins. */
async function send(options: ClientOptions, key: string, body: string, timeoutMs: number): Promise<HttpLike> {
  let timer: { cancel: () => void } | undefined
  const timeout = new Promise<never>((_, reject) => {
    timer = options.after(timeoutMs, () =>
      reject(new LinearError('timeout', `Linear did not answer in ${Math.round(timeoutMs / 1000)} s`)),
    )
  })
  const request = options.fetch(LINEAR_URL, {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: key },
    body,
  })
  try {
    return await Promise.race([request, timeout])
  } catch (error) {
    if (error instanceof LinearError) throw error
    throw new LinearError('network', `Linear unreachable: ${messageOf(error)}`)
  } finally {
    timer?.cancel()
  }
}

/** The status and the body, read as Linear reports failures: a code in `errors`, or an HTTP status. */
function decode(response: HttpLike, limit: RateLimit | undefined): unknown {
  if (response.status === 401 || response.status === 403) throw new LinearError('auth', 'Linear rejected the key')
  if (response.status === 429) throw new LinearError('ratelimited', 'rate limited by Linear', limit?.resetAt)
  let body: unknown
  try {
    body = JSON.parse(response.text)
  } catch {
    throw new LinearError('parse', `Linear answered ${response.status} with no JSON`)
  }
  if (!isRecord(body)) throw new LinearError('parse', 'Linear answered with no object')
  const error = firstGraphqlError(body.errors)
  if (error?.code === 'RATELIMITED') throw new LinearError('ratelimited', 'rate limited by Linear', limit?.resetAt)
  if (error?.code === 'AUTHENTICATION_ERROR') throw new LinearError('auth', 'Linear rejected the key')
  if (error) throw new LinearError('graphql', error.message)
  if (!response.ok) throw new LinearError('network', `Linear answered ${response.status}`)
  return body.data
}

export function linearSource(options: ClientOptions): Source & { rateLimit: () => RateLimit | undefined } {
  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS
  let limit: RateLimit | undefined

  async function gql(query: string, variables: Record<string, unknown>): Promise<unknown> {
    const key = options.key()
    if (!key) throw new LinearError('no-key', 'no Linear key')
    const response = await send(options, key, JSON.stringify({ query, variables }), timeoutMs)
    const seen = rateLimitOf(response.headers)
    if (seen) {
      limit = seen
      options.onRateLimit?.(seen)
    }
    return decode(response, limit)
  }

  async function issues(scope: Scope): Promise<IssueSummary[]> {
    const filter = issueFilterOf(scope)
    const all: IssueSummary[] = []
    let after: string | undefined
    for (let page = 0; page < MAX_PAGES; page++) {
      const parsed = parseIssuesPage(await gql(ISSUES_QUERY, { filter, after: after ?? null }))
      all.push(...parsed.issues)
      after = parsed.after
      if (!after) break
    }
    return all
  }

  return {
    kind: 'linear',
    refPattern: /^[A-Z]{2,10}-\d+$/,
    rateLimit: () => limit,
    projects: async () =>
      parseProjects(
        options.teamId ? await gql(PROJECTS_QUERY, { teamId: options.teamId }) : await gql(FIRST_TEAM_PROJECTS_QUERY, {}),
      ),
    issues,
    issue: async ref => parseIssue(await gql(ISSUE_QUERY, { id: ref })),
  }
}

